head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[autoComplete > P > allOption]<br/>AutoComplete 컴포넌트에 '전체 선택'을 의미하는 아이템을 추가할지 설정합니다.",
    "validation" : [
        "true 설정 시, '전체 선택'을 의미하는 아이템을 첫번째 아이템으로 자동으로 추가합니다.",
        "true 설정 시, 아이템의 Label 은 '-전체-', 아이템의 Value 는 'all' 로 설정됩니다.",
        "false 설정 시, '전체 선택' 아이템을 추가하지 않습니다.",
        "미설정 시, '전체 선택' 아이템을 추가하지 않습니다.",
        "'전체 선택' 아이템은 일반 아이템과 동일하게 취급되며 해당 아이템 선택 시 아이템이 선택된 것으로 처리됩니다.",
        "'전체 선택' 아이템이 추가되면 나머지 일반 아이템의 인덱스는 1 씩 증가합니다.",
        "chooseOption='true' 이면 '선택 안내' 아이템이 0 번 인덱스, '전체 선택' 아이템이 1 번 인덱스로 추가됩니다.",
        "sortOption 속성으로 아이템을 정렬해도 '전체 선택' 아이템은 정렬되지 않고 일반 아이템보다 앞에 표시됩니다.",
        "입력창에 검색어를 입력하면 검색 결과가 있는 경우 '전체 선택' 아이템이 검색 결과의 첫번째에 함께 표시됩니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 아이템 DataList 생성 (정렬 전 순서 : Incheon, Seoul, Busan, Sejong)
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' baseNode="list" repeatNode="map" id="dlt_city">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="label" name="label" dataType="text"></w2:column>';
    strDlt += '<w2:column id="value" name="value" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_city.setJSON([
        { "label" : "Incheon", "value" : "3" },
        { "label" : "Seoul", "value" : "1" },
        { "label" : "Busan", "value" : "4" },
        { "label" : "Sejong", "value" : "2" }
    ]);

    // con_allOption 기본값 true
    con_allOption.setValue("2");

    // 리스트창 확인 버튼 클릭 시 목록이 먼저 닫히므로 mousedown capture 단계에서 표시 아이템을 기록
    btn_getListInfo.render.addEventListener("mousedown", scwin.captureListState, true);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] 아이템(DataList 순서) : Incheon(3) / Seoul(1) / Busan(4) / Sejong(2)\n[절차]\n1. 화살표 버튼으로 목록을 열어 Seoul 선택 후 다시 -전체- 선택 -> 아이템 확인\n2. 입력창에 Se 입력 -> 목록이 열린 상태에서 리스트창 확인"', '', 'label1');

    let properties = {
        allOption : con_allOption.getText(),
        chooseOption : con_chooseOption.getText(),
        sortOption : con_sortOption.getValue(),
    }

    let cList = $c.gcm.createCList(properties);

    let strTarget = '';
    strTarget += '<w2:autoComplete ' + $c.gcm.getNameSpace() + ' ' + cList + ' style="width:200px; height:30px;">';
    strTarget += '<w2:choices>';
    strTarget += '<w2:itemset nodeset="data:dlt_city">';
    strTarget += '<w2:label ref="label"></w2:label>';
    strTarget += '<w2:value ref="value"></w2:value>';
    strTarget += '</w2:itemset>';
    strTarget += '</w2:choices>';
    strTarget += '</w2:autoComplete>';

    await $p.dynamicCreate("target1", "autoComplete", strTarget, $c.gcm.getTestGroup());
}



// 아이템 인덱스별 Label (Value) 와 선택 상태 출력 (validation 1 ~ 8)
scwin.btn_getItemInfo_onclick = function (e) {
    let arrItem = [];
    for (let i = 0; i < target1.getItemCount(); i++) {
        let item = target1.getItem(i);
        arrItem.push("[" + i + "] " + item.label + " (" + item.value + ")");
    }
    wf_body_bottom.getObj("scwin").setReturnValue("아이템 : " + arrItem.join(" / "));
    wf_body_bottom.getObj("scwin").setReturnValue("선택 인덱스 : " + target1.getSelectedIndex() + " / Label : " + target1.getText() + " / Value : " + target1.getValue());
};



// 버튼 mousedown 시점(목록이 닫히기 전)의 리스트창 표시 아이템 기록
scwin.captureListState = function (e) {
    scwin.listState = null;
    let itemTableElem = document.querySelector("[id='" + target1.id + "_itemTable']");
    if (!itemTableElem || getComputedStyle(itemTableElem).display === "none" || getComputedStyle(itemTableElem).visibility === "hidden") {
        return;
    }
    let rowElems = itemTableElem.querySelectorAll("[id='" + target1.id + "_itemTable_main'] tr, li");
    scwin.listState = Array.prototype.filter.call(rowElems, function (row) {
        return row.offsetParent !== null;
    }).map(function (row) {
        return row.textContent;
    });
};



// 열린 리스트창의 표시 아이템 출력 (validation 9)
scwin.btn_getListInfo_onclick = function (e) {
    if (!scwin.listState) {
        wf_body_bottom.getObj("scwin").setReturnValue("리스트창 열림 : false");
        return;
    }
    wf_body_bottom.getObj("scwin").setReturnValue("입력값 : " + document.querySelector("input[id='" + target1.id + "_input']").value + " -> 리스트창 아이템 : " + scwin.listState.join(" / "));
};
